public static int purchases0(int[] prices, int budget) {
    if (prices == null) return 0;
    int steps = 0;
    for (int i = 0; i < prices.length; i++) {
        if (prices[i] < 0 || prices[i] > budget) continue;
        budget -= prices[i];
        steps++;
    }
    return steps;
}

